func main(){os.Setenv("SYSTEM_SIGNING_KEY","migration-storage-test-key-32-bytes");os.Unsetenv("SYSTEM_AES_KEY");out:=map[string]interface{}{};paths:=[]string{"local://1/exports/a.png","local://1/doc/raw.pdf","s3://bucket/prefix/9/exports/a","oss://bucket/exports/9/a","storage://999/local://1/exports/a","storage://backend/local://1/a","storage:///local://1/a","storage://backend/"," storage://backend/local://1/a ","local://0/1/exports/a","s3://123/9/exports/a","dummy://1/a","invalid://1/a","local://18446744073709551615/exports/a","local://18446744073709551616/1/a","local://+1/a","local://01/exports/a","local://1/exports2/a","resource://abcdefghijklmnopqrstuv","\u00a0resource://abcdefghijklmnopqrstuv\u0085","resource://abcdefghijklmnopqrstuvw","resource://abcdefghijklmnopqrstuv/","storage:// x /local://1/a"};rows:=[]interface{}{};for _,p:=range paths{id,inner,ok:=types.ParseStorageBackendPath(p);handle,resource:=types.ParseResourcePath(p);rows=append(rows,map[string]interface{}{"path":p,"backend":id,"inner":inner,"scoped":ok,"provider":types.ParseProviderScheme(p),"handle":handle,"resource":resource,"tenant":strconv.FormatUint(utils.ParseTenantIDFromStoragePath(p),10),"tenant_scope":utils.ValidateStoragePathTenant(p,1)==nil,"export_scope":utils.ValidateKBScopedStoragePath(p,1)==nil})};out["paths"]=rows
signs:=[]interface{}{};for _,base:=range []string{"https://files.example.test","https://files.example.test///","https://files.example.test/prefix","https://files.example.test?z=last&a=first","https://files.example.test#frag","https://files.example.test?file_path=old&expires=3&z=x&z=y","https://files.example.test?bad=%zz&ok=yes","https://files.example.test/prefix space"}{for _,path:=range []string{"local://1/exports/图 a*~.png","storage://backend/s3://bucket/18446744073709551615/a?x#y"}{tenant:=uint64(1);if path[0]=='s'{tenant=^uint64(0)};signed,err:=utils.SignFileURL(base,path,tenant,0);if err!=nil{panic(err)};u,_:=url.Parse(signed);expires,_:=strconv.ParseInt(u.Query().Get("expires"),10,64);signs=append(signs,map[string]interface{}{"base":base,"path":path,"tenant":strconv.FormatUint(tenant,10),"now":expires-7200,"url":signed,"sig":u.Query().Get("sig"),"expires":u.Query().Get("expires")})}};out["signed"]=signs
// Exercise the actual Go catalog's deterministic grant derivation, including non-hour-aligned windows.
db,err:=gorm.Open(sqlite.Open(":memory:"),&gorm.Config{Logger:logger.Default.LogMode(logger.Silent)});if err!=nil{panic(err)};db.AutoMigrate(&types.StoredResource{},&types.ResourceBinding{},&types.ResourceAccessGrant{});catalog:=service.NewResourceCatalog(repository.NewResourceRepository(db));ref,err:=catalog.Register(context.Background(),1,"local://1/exports/file.txt",interfaces.ResourceRegistration{});if err!=nil{panic(err)};handle,_:=types.ParseResourcePath(ref);var resource types.StoredResource;db.Where("handle=?",handle).First(&resource);grants:=[]interface{}{};for _,ttl:=range []time.Duration{2*time.Hour,17*time.Second,13*time.Millisecond}{db.Exec("DELETE FROM resource_access_grants");token,err:=catalog.CreateAccessGrant(context.Background(),ref,ttl);if err!=nil{panic(err)};var grant types.ResourceAccessGrant;db.Where("resource_id=?",resource.ID).Order("created_at DESC").First(&grant);grants=append(grants,map[string]interface{}{"id":resource.ID,"now":grant.ExpiresAt.Add(-ttl).Add(ttl/4).Format(time.RFC3339Nano),"ttl_nanos":int64(ttl),"token":token,"expires":grant.ExpiresAt.Format(time.RFC3339Nano)})};out["grants"]=grants
encoder:=json.NewEncoder(os.Stdout);encoder.SetIndent("","  ");encoder.Encode(out)}
